/*
 * mst_$alloc_segs - find room for a mapping and fill its MSTEs
 *
 * Original address: 0x00E43182 (module-local; the SAU2 map has no symbol
 * here, Ghidra carries the tree name)
 * Size: 1162 bytes (0x00E43182 .. 0x00E4360B), plus its nested procedure
 * mst_$audit_map at 0x00E430D0 (178 bytes; was Ghidra FUN_00e430d0)
 * Generated by: Claude Opus 5.5 (reviewed by Claude Fable 5.1)
 *
 * Callers: every MST_$MAP* / MST_$REMAP* / MST_$CHANGE_RIGHTS /
 * MST_$GROW_AREA variant (13 call sites, 0x00E42E92 .. 0x00E43C8A).
 *
 * Frame (link.w A6,-0x3c; D2-D7/A2-A4 saved; A5 not used):
 *   (0x08,A6) addr_hint    longword -> D7: 0 = lowest free, 0x7FFFFFFF =
 *                          highest free, anything else = exactly there
 *   (0x0C,A6) uid          -> A2
 *   (0x10,A6) start_va     longword object byte offset -> D6
 *   (0x14,A6) length       longword
 *   (0x18,A6) area_size    longword, handed to mst_$lookup_object
 *   (0x1C,A6) asid         word -> D5w; forced to 0 for a fixed address in
 *                          global A space (0x00E4339A)
 *   (0x1E,A6) prot         word: mst_$lookup_object's rights and the MSTE
 *                          protection (mst_$set_mstes argument 8)
 *   (0x20,A6) touch_count  word (mst_$set_mstes argument 6)
 *   (0x22,A6) wired        byte (`tst.b`): skips the object-length clamps
 *                          and is mst_$set_mstes argument 9
 *   (0x24,A6) b_space      byte (`tst.b`): private B / global B instead of
 *                          private A / global A
 *   (0x26,A6) map_info     -> longword: receives the mapped length
 *   (0x2A,A6) status
 * Locals: (-0x08) the UID's low longword (an anonymous area's handle:
 * generation, area id); (-0x0C) status; (-0x10) location; (-0x14) mapped
 * length; (-0x1C) object length; (-0x20) result VA; (-0x24) search limit;
 * (-0x28)/(-0x2A) segment cursors; (-0x32) first object segment; (-0x36)
 * a Domain boolean "range free".
 *
 * Blocks:
 *   0x00E4319A-0x00E431B2  length 0 -> 0x40002; D2 := (start + length - 1)
 *                          or 0x7FFF, or 0xFFFFFFFF if that did not exceed
 *                          start (unsigned)
 *   0x00E431B4-0x00E4324C  anonymous UID: the area (id 1..0x540, active,
 *                          generation equal) else 0x40001; location bit 31
 *                          cleared; a reversed area clamps D2 to 0x7FFFFFFF
 *                          and, unless wired, needs start >= 0x7FFFFFFF -
 *                          (virt_size - 1)
 *   0x00E43254-0x00E43284  named UID: mst_$lookup_object
 *   0x00E43288-0x00E43298  unless wired: start below the object length,
 *                          D2 clamped to length - 1
 *   0x00E4329A-0x00E432DE  mapped length; object segments (each <= 0xFFFF,
 *                          else 0x40002), segment count D4w
 *   0x00E432E0-0x00E433AC  the target range: a search window by asid and
 *                          b_space (0x40003 if too small), or the fixed
 *                          segment range inside private A or global A
 *                          (else 0x40004)
 *   0x00E433B0-0x00E433C8  ML_$LOCK(0x0C); D2w := MST_ASID_BASE[asid]
 *   0x00E433CC-0x00E43484  top-down search for D4 free MSTEs, allocating
 *                          missing page-table pages (MST_$ALLOC_TABLE_PAGE)
 *   0x00E43488-0x00E43512  bottom-up search (also the fixed-address check)
 *   0x00E43514-0x00E43522  nothing free: 0x40003
 *   0x00E43524-0x00E43550  anonymous: AREA_$THREAD_BSTES
 *   0x00E43552-0x00E4357E  mst_$set_mstes
 *   0x00E43582-0x00E4359A  ML_$UNLOCK(0x0C); *status := status
 *   0x00E4359C-0x00E435E0  the VA (B-space / global offsets added), and the
 *                          mapped length into *map_info
 *   0x00E435E4-0x00E435FA  a private anonymous mapping with auditing on:
 *                          mst_$audit_map
 *
 * Quirks: an anonymous area's location is a frame cell of which only bit 31
 * is ever written (0x00E43210) before mst_$set_mstes stores it into every
 * MSTE of the mapping; the stack garbage it otherwise carries cannot be
 * transcribed, so the C starts it at 0 (a decision, not a reading - no
 * caller frame determines the cell).  The error exits return the
 * never-written result cell (-0x20,A6) to a caller that ignores it; the C
 * returns the uninitialised local under the same diagnostic pragma
 * MST_$MAP_AREA uses (mst/map_area.c) rather than an invented NULL.
 */

#include "mst/mst_internal.h"
#include "anon/anon.h"
#include "audit/audit.h"
#include "ml/ml.h"

/* status codes (stcodes module 4) */
#define MST_AS_OBJECT_NOT_FOUND     status_$mst_object_not_found        /* 40001 */
#define MST_AS_INVALID_LENGTH       status_$mst_invalid_length          /* 40002 */
#define MST_AS_NO_SPACE             status_$no_space_available          /* 40003 */
#define MST_AS_ILLEGAL_ADDRESS      status_$reference_to_illegal_address /* 40004 */

/* `move.w #0xc,-(SP)` 0x00E433B2: the MST allocation lock */
#define MST_AS_LOCK                 0x0C
/* `cmpi.w #0x540,D4w` 0x00E431CE: AREA_$FORMAT.max_entries */
#define MST_AS_MAX_AREA_ID          0x540
/* `cmpi.l #0x7fffffff,D7` 0x00E432E4 */
#define MST_AS_HINT_TOP             0x7FFFFFFFu
/* `lsr.l #0x8` + `lsr.l #0x7`: 32K segments */
#define MST_AS_SEG_SHIFT            15
/* `lsr.w #0x6` / `andi #0x3f` / `lsl.w #0x4`: 64 MSTEs of 16 bytes a page */
#define MST_AS_MSTES_PER_PAGE       64

/* The MSTE of ASID-relative segment `seg' given the ASID's MST base. */
static mste_t *mst_$as_mste(uint16_t base, uint16_t seg)
{
    return (mste_t *)ARCH_VA_TO_PTR(
        MST_PAGE_TABLE_BASE +
        (uint32_t)MST[(uint16_t)((seg >> 6) + base)] * 0x400u +
        (uint32_t)(seg & 0x3F) * 0x10u - 0x400u);
}

/*
 * mst_$audit_map - nested procedure 0x00E430D0 (178 bytes), static link
 * `movea.l (A6),A2'.  Logs a private anonymous mapping unless it succeeded
 * in an area the current address space owns:
 *   0x00E430D8-0x00E43102  *status = 0x40001 logs; otherwise skip when the
 *                          area's owner_asid is PROC1_$AS_ID
 *   0x00E43104-0x00E43174  event UID {0x00040022, 0}, flag 0 (success) or 1,
 *                          eight data bytes: area id, generation, owner
 *                          ASID, prot; AUDIT_$LOG_EVENT
 */
static void mst_$audit_map(uint32_t handle, uint16_t prot, status_$t *status)
{
    area_$entry_t *entry;
    uid_t event;                    /* (-0x18,A6) */
    uint16_t flag;                  /* (-0x22,A6) */
    uint16_t data[4];               /* (-0x10,A6) */
    uint16_t data_len;              /* (-0x20,A6) */
    uint16_t area_id = (uint16_t)handle;

    /* 0x00E430D8-0x00E43102 */
    entry = AREA_ID_TO_ENTRY(area_id);
    if (*status != MST_AS_OBJECT_NOT_FOUND &&
        entry->owner_asid == (int16_t)PROC1_$AS_ID) {
        return;
    }

    /* 0x00E43104-0x00E4311C: bytes 00 04 00 22 00 00 00 00 */
    data_len = 8;
    event.high = 0x00040022;
    event.low = 0;

    /* 0x00E43120-0x00E43132 */
    flag = (*status == status_$ok) ? 0 : 1;

    /* 0x00E43134-0x00E4315A */
    data[0] = area_id;
    data[1] = (uint16_t)(handle >> 16);
    data[2] = (uint16_t)entry->owner_asid;
    data[3] = prot;

    /* 0x00E43160-0x00E43174 */
    AUDIT_$LOG_EVENT(&event, &flag, status, (char *)data, &data_len);
}

/* The error exits return the never-written (-0x20,A6) cell (see the header);
 * the diagnostics are silenced for the whole function because clang reports
 * the uninitialised use at each `goto out' site. */
#if defined(__GNUC__)
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wuninitialized"
#endif
#if defined(__clang__)
#pragma clang diagnostic ignored "-Wsometimes-uninitialized"
#pragma clang diagnostic ignored "-Wconditional-uninitialized"
#endif
void *mst_$alloc_segs(uint32_t addr_hint, uid_t *uid, uint32_t start_va, uint32_t length,
                      uint32_t area_size, int16_t asid, uint16_t prot, uint16_t touch_count,
                      uint8_t wired, boolean b_space, void *map_info,
                      status_$t *status)
{
    uint32_t handle = 0;            /* (-0x8,A6): uid->low of an area */
    status_$t st;                   /* (-0xc,A6) */
    uint32_t location = 0;          /* (-0x10,A6), see the quirk above */
    uint32_t mapped;                /* (-0x14,A6) */
    uint32_t obj_len;               /* (-0x1c,A6) / D0 */
    uint32_t result_va;             /* (-0x20,A6): written only on success */
    uint16_t limit;                 /* (-0x24,A6) */
    uint16_t end;                   /* (-0x28,A6) */
    uint16_t cur;                   /* (-0x2a,A6) */
    uint16_t obj_seg;               /* (-0x32,A6) */
    int8_t all_free;                /* (-0x36,A6) */
    uint32_t last;                  /* D2 */
    uint32_t last_seg, first_seg;   /* D1, D0 */
    uint16_t count;                 /* D4w */
    uint16_t lo;                    /* D3w */
    uint16_t target;                /* D0w */
    uint16_t base;                  /* D2w */
    uint16_t s;                     /* D3w on the bottom-up search */
    area_$entry_t *entry;

    /* 0x00E4319A-0x00E431A2 */
    if (length == 0) {
        *status = MST_AS_INVALID_LENGTH;
        goto out;
    }

    /* 0x00E431A4-0x00E431B2 */
    last = (start_va + length - 1) | 0x7FFF;
    if (!(last > start_va)) {
        last = 0xFFFFFFFFu;
    }

    if (uid->high == ANON_$UID.high) {
        /* 0x00E431C0-0x00E431FC */
        handle = uid->low;
        if ((uint16_t)handle == 0 || (uint16_t)handle > MST_AS_MAX_AREA_ID) {
            *status = MST_AS_OBJECT_NOT_FOUND;
            goto out;
        }
        entry = AREA_ID_TO_ENTRY((uint16_t)handle);
        if ((entry->flags & AREA_FLAG_ACTIVE) == 0 ||
            (int16_t)(handle >> 16) != entry->generation) {
            *status = MST_AS_OBJECT_NOT_FOUND;
            goto out;
        }

        /* 0x00E4320C-0x00E43210 */
        st = status_$ok;
        location &= 0x7FFFFFFFu;

        if ((entry->flags & AREA_FLAG_REVERSED) != 0) {
            /* 0x00E43220-0x00E4324C */
            if (last > 0x7FFFFFFFu) {
                last = 0x7FFFFFFFu;
            }
            if (start_va > last) {
                *status = MST_AS_INVALID_LENGTH;
                goto out;
            }
            if ((int8_t)wired >= 0 &&
                !(0x7FFFFFFFu - (entry->virt_size - 1) <= start_va)) {
                *status = MST_AS_INVALID_LENGTH;
                goto out;
            }
            goto sized;
        }
        /* 0x00E4324E */
        obj_len = entry->virt_size;
    } else {
        /* 0x00E43254-0x00E43284 */
        mst_$lookup_object(uid, prot, area_size, &location, &obj_len, &st);
        if (st != status_$ok) {
            *status = st;
            goto out;
        }
    }

    /* 0x00E43288-0x00E43298 */
    if ((int8_t)wired >= 0) {
        if (obj_len <= start_va) {
            *status = MST_AS_INVALID_LENGTH;
            goto out;
        }
        if (!(last < obj_len)) {
            last = obj_len - 1;
        }
    }

sized:
    /* 0x00E4329A-0x00E432C0 */
    mapped = last - start_va + 1;
    last_seg = last >> MST_AS_SEG_SHIFT;
    if (last_seg > 0xFFFF) {
        *status = MST_AS_INVALID_LENGTH;
        goto out;
    }
    first_seg = start_va >> MST_AS_SEG_SHIFT;
    if (first_seg > 0xFFFF) {
        *status = MST_AS_INVALID_LENGTH;
        goto out;
    }

    /* 0x00E432D0-0x00E432DE */
    obj_seg = (uint16_t)first_seg;
    count = (uint16_t)((uint16_t)last_seg - (uint16_t)first_seg + 1);
    target = (uint16_t)(addr_hint >> MST_AS_SEG_SHIFT);

    if (addr_hint == 0 || addr_hint == MST_AS_HINT_TOP) {
        /* 0x00E432EC-0x00E43338: the search window [lo, limit) */
        if (asid == 0) {
            if (b_space >= 0) {
                lo = 0;
                limit = MST_$GLOBAL_A_SIZE;
            } else {
                lo = MST_$GLOBAL_A_SIZE;
                limit = (uint16_t)(MST_$SEG_HIGH - MST_$SEG_GLOBAL_B_OFFSET);
            }
        } else {
            if (b_space < 0) {
                lo = MST_$PRIVATE_A_SIZE;
                limit = MST_$SEG_TN;
            } else {
                lo = 0;
                limit = MST_$PRIVATE_A_SIZE;
            }
        }
        /* 0x00E4333A-0x00E4334E */
        if ((uint16_t)(limit - lo) < count) {
            *status = MST_AS_NO_SPACE;
            goto out;
        }
    } else {
        /* 0x00E43352-0x00E4335E: the fixed range [target, limit] */
        limit = (uint16_t)(target + count - 1);
        if (target > limit) {
            *status = MST_AS_ILLEGAL_ADDRESS;
            goto out;
        }
        if (target <= MST_$SEG_PRIVATE_A_END && limit <= MST_$SEG_PRIVATE_A_END) {
            /* 0x00E4336E */
            lo = target;
        } else {
            /* 0x00E43372-0x00E4339A */
            if (target < MST_$SEG_GLOBAL_A ||
                target > MST_$SEG_GLOBAL_A_END || limit > MST_$SEG_GLOBAL_A_END) {
                *status = MST_AS_ILLEGAL_ADDRESS;
                goto out;
            }
            lo = (uint16_t)(target - MST_$SEG_GLOBAL_A);
            limit = (uint16_t)(limit - MST_$SEG_GLOBAL_A);
            asid = 0;
        }
        /* 0x00E433AC */
        limit++;
    }

    /* 0x00E433B0-0x00E433C8 */
    ML_$LOCK(MST_AS_LOCK);
    base = MST_ASID_BASE[asid];

    if (addr_hint == MST_AS_HINT_TOP) {
        /* ---- top-down: 0x00E433D6-0x00E43484 ---- */
        lo = (uint16_t)(lo + count);
        end = limit;
        do {
            /* 0x00E433EA-0x00E433F4 */
            cur = (uint16_t)(end - count);
            all_free = -1;
            do {
                /* 0x00E433F8-0x00E43408 */
                if (MST[(uint16_t)((cur >> 6) + base)] != 0) {
                    /* 0x00E4340A-0x00E43436 */
                    if (mst_$as_mste(base, cur)->uid.high != 0) {
                        end = cur;
                        all_free = 0;
                        break;
                    }
                    cur++;
                } else {
                    /* 0x00E4343C-0x00E4345E */
                    st = MST_$ALLOC_TABLE_PAGE((uint16_t)asid, cur,
                                               &MST[(uint16_t)((cur >> 6) + base)]);
                    if (st != status_$ok) {
                        goto unlock;
                    }
                    cur = (uint16_t)(cur + (MST_AS_MSTES_PER_PAGE - (cur & 0x3F)));
                }
                /* 0x00E43462-0x00E4346A */
            } while (cur < end);
            /* 0x00E4346C-0x00E43476 */
        } while (all_free >= 0 && lo <= end);

        /* 0x00E4347A-0x00E43480 */
        cur = (uint16_t)(end - count);
    } else {
        /* ---- bottom-up: 0x00E43488-0x00E43512 ---- */
        limit = (uint16_t)(limit - count);
        cur = lo;
        do {
            /* 0x00E4349C-0x00E434A4 */
            s = (uint16_t)(count + cur);
            all_free = -1;
            do {
                /* 0x00E434A8-0x00E434B2 */
                s--;
                if (MST[(uint16_t)((s >> 6) + base)] != 0) {
                    /* 0x00E434B8-0x00E434E0 */
                    if (mst_$as_mste(base, s)->uid.high != 0) {
                        cur = (uint16_t)(s + 1);
                        all_free = 0;
                        break;
                    }
                } else {
                    /* 0x00E434E2-0x00E434FC */
                    st = MST_$ALLOC_TABLE_PAGE((uint16_t)asid, s,
                                               &MST[(uint16_t)((s >> 6) + base)]);
                    if (st != status_$ok) {
                        goto unlock;
                    }
                    s = (uint16_t)(s - (s & 0x3F));
                }
                /* 0x00E434FE-0x00E43502 */
            } while (s > cur);
            /* 0x00E43504-0x00E43512 */
        } while (all_free >= 0 && cur <= limit);
    }

    /* 0x00E43514-0x00E43522 */
    if (all_free >= 0) {
        st = MST_AS_NO_SPACE;
        goto unlock;
    }

    /* 0x00E43524-0x00E43550: the two words count, obj_seg form THREAD_BSTES'
     * longword at (0x10,A6) (pushed obj_seg first, so count is its high
     * half); the callee never reads it */
    if (uid->high == ANON_$UID.high) {
        AREA_$THREAD_BSTES(&handle, (int16_t)asid, (int16_t)cur,
                           ((uint32_t)count << 16) | obj_seg, &st);
        if (st != status_$ok) {
            goto unlock;
        }
    }

    /* 0x00E43552-0x00E4357E */
    mst_$set_mstes(uid, obj_seg, location, cur, (uint16_t)(count + cur - 1),
                   touch_count, (uint16_t)asid, prot, (int8_t)wired);

unlock:
    /* 0x00E43582-0x00E4359A */
    ML_$UNLOCK(MST_AS_LOCK);
    *status = st;
    if (st != status_$ok) {
        goto out;
    }

    /* 0x00E4359C-0x00E435C2 */
    if (asid == 0) {
        cur = (uint16_t)(cur + ((b_space < 0) ? MST_$SEG_GLOBAL_B_OFFSET
                                              : MST_$SEG_GLOBAL_A));
    } else if (b_space < 0) {
        cur = (uint16_t)(cur + MST_$SEG_PRIVATE_B_OFFSET);
    }

    /* 0x00E435C6-0x00E435E0 */
    result_va = (start_va & 0x7FFF) + ((uint32_t)cur << MST_AS_SEG_SHIFT);
    *(uint32_t *)map_info = mapped;

out:
    /* 0x00E435E4-0x00E435FA */
    if (asid != 0 && uid->high == ANON_$UID.high && AUDIT_$ENABLED < 0) {
        mst_$audit_map(handle, prot, status);
    }
    /* 0x00E435FE: `movea.l (-0x20,A6),A0` on every exit, written only at
     * 0x00E435D8 (see the header) */
    return ARCH_VA_TO_PTR(result_va);
}
#if defined(__GNUC__)
#pragma GCC diagnostic pop
#endif
